const games=[{id:'arithmetic',category:'number',name:'번개 암산',desc:'머릿속 계산기를 깨워봐!<br>빠르게 풀수록 자신감도 쑥쑥.',art:'7×8',symbol:'ϟ',tag:'QUICK THINKING',level:'연산',time:'10문제'},{id:'sequence',category:'logic',name:'다음 숫자는?',desc:'숫자 사이에 숨은 비밀.<br>규칙을 찾는 순간, 유레카!',art:'? →',symbol:'✳',tag:'FIND THE PATTERN',level:'추리 · 규칙',time:'10문제'},{id:'fraction',category:'fraction',name:'분수 피크닉',desc:'반 조각, 두 조각, 세 조각.<br>같은 크기의 분수를 찾아봐.',art:'½',symbol:'◒',tag:'PIECE OF CAKE',level:'분수',time:'10문제'},{id:'compare',category:'number',name:'누가 더 클까',desc:'비슷해 보여도 다른 숫자.<br>더 큰 쪽을 콕 골라봐!',art:'< >',symbol:'★',tag:'BIGGER & BETTER',level:'수 감각',time:'10문제'}];
let stats={plays:0,best:0,correct:0};try{const saved=JSON.parse(localStorage.getItem('mathclub-records'));if(saved&&['plays','best','correct'].every(k=>Number.isFinite(saved[k])&&saved[k]>=0))stats=saved}catch{}
const $=s=>document.querySelector(s);function renderStats(){for(const k of ['plays','best','correct'])$('#'+k).textContent=stats[k]}renderStats();
function renderCards(filter='all'){$('#cards').innerHTML=games.filter(g=>filter==='all'||g.category===filter).map(g=>`<article class="card"><div class="card-art" style="background:${({arithmetic:'#55db9c',sequence:'#e9ccff',fraction:'#4da2ff',compare:'#ffd731'})[g.id]}"><span class="corner">${g.tag}</span><span class="number">${g.art}</span><span class="orbit" aria-hidden="true">${g.symbol}</span></div><div class="card-content"><h3>${g.name}</h3><p>${g.desc}</p><div class="card-meta"><span>${g.level}</span><span>${g.time} · 약 2분</span></div><button data-game="${g.id}">플레이하기 <span>↗</span></button></div></article>`).join('')}renderCards();
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderCards(b.dataset.filter)});$('#cards').onclick=e=>{const b=e.target.closest('[data-game]');if(b)start(b.dataset.game)};$('#random').onclick=()=>start(games[rand(0,3)].id);
const dialog=$('#game');let state,previousFocus;function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a}function shuffle(a){for(let i=a.length-1;i>0;i--){let j=rand(0,i);[a[i],a[j]]=[a[j],a[i]]}return a}function numericChoices(answer){const set=new Set([answer]);while(set.size<4)set.add(Math.max(0,answer+rand(-12,12)));return shuffle([...set]).map(n=>({label:String(n),value:n}))}
function makeQuestion(){const hard=state.hard;let a,b,answer,label,choices;if(state.id==='arithmetic'){a=rand(2,hard?35:12);b=rand(2,hard?20:12);const op=rand(0,hard?2:1);if(op===0){answer=a+b;label=`${a} + ${b} = ?`}else if(op===1){answer=a*b;label=`${a} × ${b} = ?`}else{if(a<b)[a,b]=[b,a];answer=a-b;label=`${a} − ${b} = ?`}choices=numericChoices(answer)}else if(state.id==='sequence'){a=rand(1,12);b=rand(2,hard?9:5);const multiply=hard&&rand(0,1);let seq=Array.from({length:4},(_,i)=>multiply?a*b**i:a+b*i);answer=multiply?a*b**4:a+b*4;label=seq.join(', ') + ', ?';choices=numericChoices(answer)}else if(state.id==='fraction'){b=rand(2,hard?12:6);a=rand(1,b-1);const scale=rand(2,hard?6:4);answer=a*scale;label=`${a}/${b} = ?/${b*scale}`;choices=numericChoices(answer)}else{a=rand(1,hard?999:99);do{b=rand(1,hard?999:99)}while(a===b);answer=Math.max(a,b);label='더 큰 숫자는?';choices=shuffle([a,b]).map(n=>({label:String(n),value:n}))}return{label,answer,choices}}
function start(id){previousFocus=document.activeElement;state={id,hard:$('#difficulty').value==='hard',index:0,score:0,locked:false};$('#game-title').textContent=games.find(g=>g.id===id).name+' · '+(state.hard?'어려움':'쉬움');if(!dialog.open)dialog.showModal();round()}
function round(){state.locked=false;state.q=makeQuestion();$('#play-area').innerHTML=`<div class="muted">${state.index+1} / 10 문제 · ${state.score*10}점</div><div class="progress"><span style="width:${state.index*10}%"></span></div><p class="question" style="${state.id==='sequence'?'font-size:clamp(23px,5vw,36px)':''}">${state.q.label}</p><div class="answers">${state.q.choices.map((c,i)=>`<button data-choice="${i}">${c.label}</button>`).join('')}</div><p class="feedback" aria-live="polite">천천히 생각해도 괜찮아요.</p><button id="next" class="black" hidden>다음 문제 →</button>`;$('#play-area').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.choice)));$('#next').onclick=()=>{state.index++;state.index===10?finish():round()};$('#play-area').querySelector('[data-choice]').focus()}
function answer(index){if(state.locked)return;state.locked=true;const correct=state.q.choices[index].value===state.q.answer;if(correct)state.score++;$('#play-area').querySelectorAll('[data-choice]').forEach((b,i)=>{b.disabled=true;b.classList.toggle('chosen',i===index)});$('.feedback').textContent=correct?'정답! 생각하는 힘이 +1 ✳':`아깝다! 정답은 ${state.q.answer}. 다음 문제에 도전해요.`;$('#next').hidden=false;$('#next').textContent=state.index===9?'결과 보기 ↗':'다음 문제 →';$('#next').focus()}
function finish(){stats.plays++;stats.correct+=state.score;stats.best=Math.max(stats.best,state.score*10);try{localStorage.setItem('mathclub-records',JSON.stringify(stats))}catch{}renderStats();$('#play-area').innerHTML=`<div class="eyebrow">NICE PLAY!</div><div class="result-score">${state.score*10}<small style="font-size:20px">점</small></div><h2 style="font-size:28px">${state.score>=8?'오늘 두뇌 폼, 최고!':'도전한 너, 멋지다!'}</h2><p class="muted">10문제 중 ${state.score}문제를 맞혔어요.<br>다시 한 판, 새로운 문제로 만나요.</p><div class="modal-actions"><button id="again" class="black">다시 도전 ↗</button><button id="done">게임 둘러보기</button></div>`;$('#again').onclick=()=>start(state.id);$('#done').onclick=()=>dialog.close();$('#again').focus()}
$('#close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
